<"'!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Админ-панель</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --sidebar-w: 240px;
    --sidebar-collapsed-w: 64px;
    --primary: #4f46e5;
    --primary-light: #eef2ff;
    --bg: #f5f5f5;
    --surface: #fff;
    --border: #e5e7eb;
    --text: #1f2937;
    --text-secondary: #6b7280;
    --success: #22c55e;
    --warning: #f59e0b;
    --danger: #ef4444;
    --info: #3b82f6;
    --radius: 8px;
    --shadow: 0 1px 3px rgba(0,0,0,.08);
  }
  body { font-family: '"'Inter', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); display: flex; min-height: 100vh; }
  a { color: inherit; text-decoration: none; }

  /* ── Sidebar ── */
  .sidebar {
    width: var(--sidebar-w); min-width: var(--sidebar-collapsed-w);
    background: #1e1b4b; color: #c7d2fe;
    display: flex; flex-direction: column;
    transition: width .25s ease;
    position: sticky; top: 0; height: 100vh; z-index: 100;
  }
  .sidebar.collapsed { width: var(--sidebar-collapsed-w); }
  .sidebar-header {
    padding: 20px 20px 16px; display: flex; align-items: center; gap: 12px;
    border-bottom: 1px solid rgba(255,255,255,.08);
  }
  .sidebar-header .logo-icon {
    width: 32px; height: 32px; background: var(--primary); border-radius: 8px;
    display: flex; align-items: center; justify-content: center; color: #fff;
    font-weight: 800; font-size: 16px; flex-shrink: 0;
  }
  .sidebar-header .logo-text {
    font-weight: 700; font-size: 15px; color: #fff; white-space: nowrap;
    overflow: hidden; opacity: 1; transition: opacity .15s;
  }
  .sidebar.collapsed .logo-text { opacity: 0; width: 0; }
  .sidebar-nav { flex: 1; padding: 12px 12px; display: flex; flex-direction: column; gap: 2px; }
  .sidebar-nav .nav-item {
    display: flex; align-items: center; gap: 12px; padding: 10px 12px;
    border-radius: 8px; cursor: pointer; transition: background .15s;
    white-space: nowrap; font-size: 14px; font-weight: 500;
  }
  .sidebar-nav .nav-item:hover { background: rgba(255,255,255,.08); color: #fff; }
  .sidebar-nav .nav-item.active { background: var(--primary); color: #fff; }
  .nav-item .nav-icon { width: 20px; text-align: center; flex-shrink: 0; font-size: 16px; }
  .nav-item .nav-label { overflow: hidden; opacity: 1; transition: opacity .15s; }
  .sidebar.collapsed .nav-label { opacity: 0; width: 0; }
  .sidebar-footer {
    padding: 12px 12px; border-top: 1px solid rgba(255,255,255,.08);
  }
  .collapse-btn {
    display: flex; align-items: center; gap: 12px; padding: 10px 12px;
    border-radius: 8px; cursor: pointer; background: none; border: none;
    color: inherit; font-size: 14px; width: 100%; transition: background .15s;
  }
  .collapse-btn:hover { background: rgba(255,255,255,.08); color: #fff; }
  .collapse-btn .nav-icon { width: 20px; flex-shrink: 0; font-size: 16px; }

  /* ── Main ── */
  .main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
  .topbar {
    background: var(--surface); border-bottom: 1px solid var(--border);
    padding: 16px 32px; display: flex; align-items: center; justify-content: space-between;
  }
  .topbar h1 { font-size: 20px; font-weight: 700; }
  .topbar .breadcrumb { font-size: 13px; color: var(--text-secondary); }
  .content { padding: 24px 32px; flex: 1; overflow-x: auto; }

  /* ── Stats cards ── */
  .stats { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; }
  .stat-card {
    background: var(--surface); border-radius: var(--radius); padding: 20px;
    box-shadow: var(--shadow); border: 1px solid var(--border);
  }
  .stat-card .stat-label { font-size: 13px; color: var(--text-secondary); margin-bottom: 4px; }
  .stat-card .stat-value { font-size: 28px; font-weight: 700; }
  .stat-card .stat-change { font-size: 12px; margin-top: 4px; }
  .stat-change.up { color: var(--success); }
  .stat-change.down { color: var(--danger); }

  /* ── Toolbar ── */
  .toolbar {
    display: flex; align-items: center; gap: 12px; margin-bottom: 16px; flex-wrap: wrap;
  }
  .toolbar select, .toolbar button {
    padding: 8px 14px; border-radius: 6px; border: 1px solid var(--border);
    background: var(--surface); font-size: 13px; cursor: pointer;
  }
  .toolbar button:hover { background: var(--primary-light); border-color: var(--primary); }
  .toolbar button.primary { background: var(--primary); color: #fff; border-color: var(--primary); }
  .toolbar button.primary:hover { background: #4338ca; }
  .selected-count { font-size: 13px; color: var(--text-secondary); margin-left: auto; }

  /* ── Table wrapper ── */
  .table-wrapper {
    background: var(--surface); border-radius: var(--radius);
    box-shadow: var(--shadow); border: 1px solid var(--border); overflow: auto;
  }
  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  thead { position: sticky; top: 0; z-index: 10; }
  thead th {
    background: #f8fafc; padding: 12px 16px; text-align: left; font-weight: 600;
    font-size: 12px; text-transform: uppercase; letter-spacing: .04em;
    color: var(--text-secondary); border-bottom: 1px solid var(--border);
    white-space: nowrap; cursor: grab; user-select: none;
  }
  thead th:active { cursor: grabbing; }
  thead th.drag-over { background: #e0e7ff; box-shadow: inset 2px 0 0 var(--primary); }
  tbody td { padding: 12px 16px; border-bottom: 1px solid var(--border); }
  tbody tr { transition: background .12s; }
  tbody tr:hover { background: #f8fafc; }
  tbody tr.selected { background: var(--primary-light); }
  tbody tr.group-row { background: #f1f5f9; font-weight: 600; cursor: pointer; }
  tbody tr.group-row td { padding: 10px 16px; color: var(--text-secondary); font-size: 13px; }
  .group-toggle { display: inline-block; margin-right: 6px; transition: transform .2s; }
  .group-toggle.collapsed { transform: rotate(-90deg); }

  /* ── Status badge ── */
  .badge {
    display: inline-block; padding: 3px 10px; border-radius: 20px; font-size: 12px;
    font-weight: 600;
  }
  .badge.new       { background: #dbeafe; color: #1d4ed8; }
  .badge.processing{ background: #fef3c7; color: #92400e; }
  .badge.shipped   { background: #d1fae5; color: #065f46; }
  .badge.delivered { background: #e0e7ff; color: #3730a3; }
  .badge.cancelled { background: #fee2e2; color: #991b1b; }

  /* ── Checkbox ── */
  .checkbox { width: 16px; height: 16px; accent-color: var(--primary); cursor: pointer; }

  /* ── Scrollbar ── */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #d1d5db; border-radius: 3px; }

  /* ── Drag ghost ── */
  .dragging-col { opacity: 0.4; }
  th.dragging-col { opacity: 0.4; }
</style>
</head>
<body>

<"'!-- ═══════════ SIDEBAR ═══════════ -->
<aside class="sidebar" id="sidebar">
  <div class="sidebar-header">
    <div class="logo-icon">A</div>
    <span class="logo-text">Админка</span>
  </div>
  <nav class="sidebar-nav">
    <div class="nav-item active" data-page="home">
      <span class="nav-icon">🏠</span><span class="nav-label">Главная</span>
    </div>
    <div class="nav-item" data-page="users">
      <span class="nav-icon">👥</span><span class="nav-label">Пользователи</span>
    </div>
    <div class="nav-item" data-page="orders">
      <span class="nav-icon">📦</span><span class="nav-label">Заказы</span>
    </div>
    <div class="nav-item" data-page="settings">
      <span class="nav-icon">⚙️</span><span class="nav-label">Настройки</span>
    </div>
  </nav>
  <div class="sidebar-footer">
    <button class="collapse-btn" id="collapseBtn">
      <span class="nav-icon">◀</span><span class="nav-label">Свернуть</span>
    </button>
  </div>
</aside>

<!-- ═══════════ MAIN ═══════════ -->
<main class="main">
  <div class="topbar">
    <div>
      <h1 id="pageTitle">Заказы</h1>
      <span class="breadcrumb">Админка / Заказы</span>
    </div>
  </div>
  <div class="content">
    <!-- Stats -->
    <div class="stats">
      <div class="stat-card">
        <div class="stat-label">Всего заказов</div>
        <div class="stat-value" id="statTotal">0</div>
        <div class="stat-change up">▲ 12% с прошлого месяца</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">В обработке</div>
        <div class="stat-value" id="statProcessing">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Доставлено</div>
        <div class="stat-value" id="statDelivered">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Сумма (₽)</div>
        <div class="stat-value" id="statRevenue">0</div>
      </div>
    </div>

    <!-- Toolbar -->
    <div class="toolbar">
      <select id="groupBy">
        <option value="status">Группировать по статусу</option>
        <option value="none">Без группировки</option>
      </select>
      <button onclick="selectAll()">Выбрать все</button>
      <button onclick="deselectAll()">Снять выделение</button>
      <button class="primary" onclick="resetTable()">Сбросить колонки</button>
      <span class="selected-count" id="selectedCount">Выбрано: 0</span>
    </div>

    <!-- Table -->
    <div class="table-wrapper">
      <table>
        <thead id="tableHead"></thead>
        <tbody id="tableBody"></tbody>
      </table>
    </div>
  </div>
</main>

<script>
// ═══════════ DATA ═══════════
const STATUS_ORDER = ['"'new', 'processing', 'shipped', 'delivered', 'cancelled'];
const STATUS_LABEL = {
  new: 'Новый', processing: 'В обработке', shipped: 'Отправлен',
  delivered: 'Доставлен', cancelled: 'Отменён'
};

const COLUMNS_DEFAULT = [
  { key: 'id',      label: 'ID',           width: null },
  { key: 'customer', label: 'Клиент',       width: null },
  { key: 'email',   label: 'Email',         width: null },
  { key: 'product', label: 'Товар',         width: null },
  { key: 'date',    label: 'Дата',          width: null },
  { key: 'amount',  label: 'Сумма (₽)',     width: null },
  { key: 'status',  label: 'Статус',        width: null },
];

let columns = JSON.parse(JSON.stringify(COLUMNS_DEFAULT));
let orders = [];
let selectedRows = new Set();
let collapsedGroups = new Set();

// Generate mock orders
function generateOrders() {
  const customers = [
    'Иван Петров', 'Мария Смирнова', 'Алексей Иванов', 'Ольга Кузнецова',
    'Дмитрий Соколов', 'Елена Попова', 'Сергей Волков', 'Анна Морозова',
    'Павел Новиков', 'Татьяна Федорова', 'Роман Козлов', 'Юлия Лебедева',
    'Константин Егоров', 'Виктория Соловьева', 'Андрей Зайцев'
  ];
  const products = [
    'iPhone 15 Pro', 'MacBook Air M3', 'AirPods Pro', 'iPad Air',
    'Apple Watch 9', 'Samsung S24', 'Sony WH-1000XM5', 'Dell XPS 15',
    'Logitech MX Keys', 'Razer DeathAdder', 'LG OLED 55\"', 'PlayStation 5'
  ];
  const statuses = STATUS_ORDER;
  const randomDate = () => {
    const start = new Date(2026, 0, 1);
    const end = new Date(2026, 10, 6);
    const d = new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));
    return d.toISOString().slice(0, 10);
  };
  orders = [];
  for (let i = 1; i <= 40; i++) {
    orders.push({
      id: "'`#${String(i).padStart(4,'"'0')}"'`,
      customer: customers[Math.floor(Math.random() * customers.length)],
      email: `user${i}@example.com`,
      product: products[Math.floor(Math.random() * products.length)],
      date: randomDate(),
      amount: Math.floor(Math.random() * 200000 + 5000),
      status: statuses[Math.floor(Math.random() * statuses.length)],
    });
  }
}

// ═══════════ RENDER ═══════════
function renderHead() {
  const thead = document.getElementById('"'tableHead');
  thead.innerHTML = '<tr>' + columns.map((col, idx) =>
    "'`<th draggable="true" data-col="${col.key}" data-idx="${idx}"
         ondragstart="dragColStart(event)" ondragover="dragColOver(event)"
         ondragleave="dragColLeave(event)" ondrop="dragColDrop(event)"
         ondragend="dragColEnd(event)">${col.label}</th>`
  ).join('"'') + '</tr>';
}

function renderBody() {
  const tbody = document.getElementById('tableBody');
  const groupBy = document.getElementById('groupBy').value;
  let html = '';

  if (groupBy === 'status') {
    // Group by status — maintain STATUS_ORDER, show groups that have orders
    const grouped = {};
    orders.forEach(o => { (grouped[o.status] ||= []).push(o); });
    STATUS_ORDER.forEach(status => {
      const items = grouped[status] || [];
      if (items.length === 0) return;
      const isCollapsed = collapsedGroups.has(status);
      html += "'`<tr class="group-row" data-group="${status}" onclick="toggleGroup('"'"'${status}'"')\">
        <td colspan=\""'${columns.length}">
          <span class="group-toggle${isCollapsed ? '"' collapsed' : ''}\">▼</span>
          "'${STATUS_LABEL[status]} <span style="color:#9ca3af;font-weight:400;">(${items.length})</span>
        </td>
      </tr>`;
      if (!isCollapsed) {
        items.forEach(o => { html += orderRow(o); });
      }
    });
  } else {
    orders.forEach(o => { html += orderRow(o); });
  }
  tbody.innerHTML = html;
  updateStats();
}

function orderRow(o) {
  const sel = selectedRows.has(o.id) ? '"' selected' : '';
  return "'`<tr class="${sel}" data-id="${o.id}">
    ${columns.map(col => {
      if (col.key === '"'status') return "'`<td><span class="badge badge-${o.status}">${STATUS_LABEL[o.status]}</span></td>`;
      if (col.key === '"'amount') return "'`<td>${o.amount.toLocaleString('"'ru-RU')} ₽</td>"'`;
      return `<td>${o[col.key] || '"''}</td>"'`;
    }).join('"'')}
  </tr>"'`;
}

function updateStats() {
  document.getElementById('"'statTotal').textContent = orders.length;
  document.getElementById('statProcessing').textContent = orders.filter(o => o.status === 'processing').length;
  document.getElementById('statDelivered').textContent = orders.filter(o => o.status === 'delivered').length;
  document.getElementById('statRevenue').textContent =
    orders.reduce((s, o) => s + o.amount, 0).toLocaleString('ru-RU') + ' ₽';
  document.getElementById('selectedCount').textContent = "'`Выбрано: ${selectedRows.size}`;
}

// ═══════════ ROW SELECTION ═══════════
document.getElementById('"'tableBody').addEventListener('click', e => {
  const row = e.target.closest('tr[data-id]');
  if ("'!row) return;
  const id = row.dataset.id;
  if (selectedRows.has(id)) {
    selectedRows.delete(id);
  } else {
    selectedRows.add(id);
  }
  row.classList.toggle('"'selected');
  updateStats();
});

// ═══════════ GROUP TOGGLE ═══════════
function toggleGroup(status) {
  if (collapsedGroups.has(status)) collapsedGroups.delete(status);
  else collapsedGroups.add(status);
  renderBody();
}

// ═══════════ SELECT ALL / DESELECT ═══════════
function selectAll() {
  orders.forEach(o => selectedRows.add(o.id));
  renderBody();
}
function deselectAll() {
  selectedRows.clear();
  renderBody();
}

// ═══════════ COLUMN DRAG & DROP ═══════════
let dragSrcIdx = null;

function dragColStart(e) {
  dragSrcIdx = parseInt(e.target.dataset.idx);
  e.target.classList.add('dragging-col');
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', e.target.dataset.col);
}

function dragColOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  const th = e.target.closest('th');
  if (th && parseInt(th.dataset.idx) "'!== dragSrcIdx) {
    th.classList.add('"'drag-over');
  }
}

function dragColLeave(e) {
  const th = e.target.closest('th');
  if (th) th.classList.remove('drag-over');
}

function dragColDrop(e) {
  e.preventDefault();
  const th = e.target.closest('th');
  if ("'!th) return;
  th.classList.remove('"'drag-over');
  const dstIdx = parseInt(th.dataset.idx);
  if (dragSrcIdx === null || dragSrcIdx === dstIdx) return;
  const [moved] = columns.splice(dragSrcIdx, 1);
  columns.splice(dstIdx, 0, moved);
  dragSrcIdx = null;
  renderAll();
}

function dragColEnd(e) {
  e.target.classList.remove('dragging-col');
  document.querySelectorAll('th.drag-over').forEach(th => th.classList.remove('drag-over'));
}

function resetTable() {
  columns = JSON.parse(JSON.stringify(COLUMNS_DEFAULT));
  renderAll();
}

function renderAll() {
  renderHead();
  renderBody();
}

// ═══════════ SIDEBAR ═══════════
const sidebar = document.getElementById('sidebar');
const collapseBtn = document.getElementById('collapseBtn');
collapseBtn.addEventListener('click', () => {
  sidebar.classList.toggle('collapsed');
  const icon = collapseBtn.querySelector('.nav-icon');
  const label = collapseBtn.querySelector('.nav-label');
  if (sidebar.classList.contains('collapsed')) {
    icon.textContent = '▶';
    label.textContent = 'Развернуть';
  } else {
    icon.textContent = '◀';
    label.textContent = 'Свернуть';
  }
});

// Nav active switching
document.querySelectorAll('.nav-item').forEach(item => {
  item.addEventListener('click', () => {
    document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
    item.classList.add('active');
    document.getElementById('pageTitle').textContent =
      item.querySelector('.nav-label').textContent;
  });
});

// Group by change
document.getElementById('groupBy').addEventListener('change', () => {
  collapsedGroups.clear();
  renderBody();
});

// ═══════════ INIT ═══════════
generateOrders();
renderAll();
</script>
</body>
</html>
